const b64=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0));};const b64s=b=>{let s='';new Uint8Array(b).forEach(x=>s+=String.fromCharCode(x));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};const status=document.querySelector('#passkey-status');
document.querySelector('#passkey-login').onclick=async()=>{try{if(!window.PublicKeyCredential){status.textContent='Este navegador não oferece biometria WebAuthn.';return;}const email=document.querySelector('#login-email').value.trim();if(!email){status.textContent='Informe seu e-mail primeiro.';return;}status.textContent='Aguardando biometria…';const start=await fetch('webauthn_login_begin.php?email='+encodeURIComponent(email));const data=await start.json();if(!start.ok)throw Error(data.error||'Não foi possível iniciar.');const p=data.publicKey;p.challenge=b64(p.challenge);p.allowCredentials=p.allowCredentials.map(c=>({...c,id:b64(c.id)}));const cred=await navigator.credentials.get({publicKey:p});const body={id:cred.id,rawId:b64s(cred.rawId),type:cred.type,response:{clientDataJSON:b64s(cred.response.clientDataJSON),authenticatorData:b64s(cred.response.authenticatorData),signature:b64s(cred.response.signature),userHandle:cred.response.userHandle?b64s(cred.response.userHandle):null}};const finish=await fetch('webauthn_login_finish.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await finish.json();if(!finish.ok)throw Error(result.error||'Biometria recusada.');location.href=result.redirect;}catch(e){status.textContent=e.message||'Biometria cancelada.';}};
</script></body></html>
